      hu: "Népszerű nemzeti park Nyugat-Jáván, amely a Gunung Gede és a Gunung Pangrango ikervulkánokat foglalja magában. Túraútvonalairól és gazdag madárvilágáról ismert.",
      ro: "Un parc național popular în vestul Javei, care cuprinde vulcanii gemeni Muntele Gede și Muntele Pangrango. Cunoscut pentru traseele sale de drumeție și avifauna bogată.",
      en: "A popular national park in West Java, encompassing the twin volcanoes Mount Gede and Mount Pangrango. Known for its hiking trails and rich birdlife.",
