      en: "A unique wetland of seasonal lakes and swamp forests in West Kalimantan, renowned for its enormous fish diversity.",
      es: "Un humedal único compuesto por lagos estacionales y bosques pantanosos en Kalimantan Occidental, conocido por su enorme diversidad de peces.",
