    descriptionAdvanced: {
      de: "Der Merapi ist einer der aktivsten und gefährlichsten Vulkane der Welt und liegt auf der Insel Java, nahe der Stadt Yogyakarta. Sein Name bedeutet in der Landessprache 'Feuerberg', was seine ständige vulkanische Aktivität treffend beschreibt. Der Stratovulkan erreicht eine Höhe von etwa 2.910 Metern und ist für seine gewaltigen pyroklastischen Ströme bekannt, die bei Ausbrüchen mit hoher Geschwindigkeit die Hänge hinabstürzen. Schwere Eruptionen in den Jahren 1930 und 2010 forderten zahlreiche Todesopfer und führten zu großflächigen Evakuierungen. Trotz der ständigen Gefahr ist die Umgebung aufgrund der fruchtbaren Vulkanasche dicht besiedelt und intensiv landwirtschaftlich genutzt. In der javanischen Kosmologie nimmt der Merapi einen zentralen Platz ein und ist eng mit dem Sultanat von Yogyakarta und dem Indischen Ozean verbunden. Regelmäßige Opferrituale der lokalen Bevölkerung spiegeln den tiefen Respekt vor der Naturgewalt des Berges wider.",
      hu: "A Merapi a világ egyik legaktívabb és legveszélyesebb vulkánja, Jáva szigetén, Yogyakarta városának közelében található. Neve helyi nyelven 'Tűzhegyet' jelent, ami találóan leírja folyamatos vulkáni tevékenységét. A rétegvulkán körülbelül 2910 méter magas, és híres hatalmas piroklasztikus árjairól, amelyek a kitörések során nagy sebességgel zúdulnak le a lejtőkön. Az 1930-as és a 2010-es súlyos kitörések számos áldozatot követeltek, és nagyszabású kitelepítésekhez vezettek. A folyamatos veszély ellenére a környék a termékeny vulkáni hamu miatt sűrűn lakott és intenzíven művelt mezőgazdasági terület. A jávai kozmológiában a Merapi központi helyet foglal el, szoros kapcsolatban áll a yogyakartai szultanátussal és az Indiai-óceánnal. A helyi lakosság rendszeres áldozati rítusai a hegy természeti ereje iránti mély tiszteletet tükrözik.",
      ro: "Muntele Merapi este unul dintre cei mai activi și periculoși vulcani din lume, fiind situat pe insula Java, lângă orașul Yogyakarta. Numele său înseamnă 'Muntele de Foc', o descriere fidelă a activității sale vulcanice cvasi-permanente. Acest stratovulcan atinge o altitudine de aproximativ 2.910 metri și este cunoscut pentru fluxurile piroclastice devastatoare care coboară pantele cu viteze enorme în timpul erupțiilor. Erupțiile majore din 1930 și 2010 au provocat numeroase victime și au necesitat evacuări pe scară largă. În ciuda riscului constant, solul vulcanic fertil atrage o populație densă care practică agricultura intensivă în apropierea sa. În cosmologia javaneză, Merapi ocupă un loc central, fiind legat spiritual de Sultanatul din Yogyakarta și de Oceanul Indian. Ritualurile periodice efectuate de localnici reflectă respectul profund față de forța imprevizibilă a muntelui.",
      en: "Mount Merapi is among the most active and dangerous volcanoes in the world, situated on the island of Java near the major city of Yogyakarta. Its name translates to 'Mountain of Fire,' reflecting its near-constant volcanic activity over centuries. This stratovolcano rises to an elevation of approximately 2,910 meters and is notorious for its deadly pyroclastic flows, which can reach high speeds during eruptions. Significant volcanic events in 1930 and 2010 caused substantial loss of life and displaced hundreds of thousands of residents. Despite the inherent dangers, the surrounding slopes are densely populated due to the highly fertile volcanic soil that supports intensive agriculture. Merapi holds deep cultural and spiritual significance in Javanese tradition, forming a symbolic axis with the Kraton of Yogyakarta and the Southern Sea. Local communities continue to perform traditional ceremonies to appease the spirits believed to dwell within the mountain.",
      es: "El Merapi es uno de los volcanes más activos y peligrosos del mundo y se encuentra en la isla de Java, cerca de la ciudad de Yogyakarta. Su nombre significa en el idioma local 'Montaña de Fuego', lo que describe acertadamente su constante actividad volcánica. El estratovolcán alcanza una altura de unos 2.910 metros y es conocido por sus enormes flujos piroclásticos, que descienden por las laderas a gran velocidad durante las erupciones. Graves erupciones en 1930 y 2010 se cobraron numerosas víctimas y provocaron evacuaciones a gran escala. A pesar del peligro constante, los alrededores están densamente poblados y se utilizan intensivamente para la agricultura debido a la fértil ceniza volcánica. En la cosmología javanesa, el Merapi ocupa un lugar central y está estrechamente vinculado al sultanato de Yogyakarta y al Océano Índico. Los rituales de sacrificio regulares de la población local reflejan el profundo respeto por el poder natural de la montaña.",
      pt: "O Merapi é um dos vulcões mais ativos e perigosos do mundo e situa-se na ilha de Java, perto da cidade de Yogyakarta. O seu nome significa na língua local 'Montanha de Fogo', o que descreve com precisão a sua constante atividade vulcânica. O estratovulcão atinge uma altitude de cerca de 2.910 metros e é conhecido pelos seus enormes fluxos piroclásticos, que descem as encostas a alta velocidade durante as erupções. Erupções graves em 1930 e 2010 causaram inúmeras vítimas mortais e levaram a evacuações em grande escala. Apesar do perigo constante, os arredores são densamente povoados e intensamente utilizados para a agricultura devido às férteis cinzas vulcânicas. Na cosmologia javanesa, o Merapi ocupa um lugar central e está estreitamente ligado ao sultanato de Yogyakarta e ao Oceano Índico. Os rituais de sacrifício regulares da população local refletem o profundo respeito pelo poder natural da montanha.",
      fr: "Le Merapi est l'un des volcans les plus actifs et les plus dangereux au monde, situé sur l'île de Java, près de la ville de Yogyakarta. Son nom signifie 'Montagne de Feu' dans la langue locale, ce qui décrit parfaitement son activité volcanique constante. Ce stratovolcan culmine à environ 2 910 mètres et est réputé pour ses énormes coulées pyroclastiques qui dévalent les pentes à grande vitesse lors des éruptions. De graves éruptions en 1930 et 2010 ont fait de nombreuses victimes et entraîné des évacuations massives. Malgré le danger permanent, les environs sont densément peuplés et intensément cultivés grâce aux cendres volcaniques fertiles. Dans la cosmologie javanaise, le Merapi occupe une place centrale et est étroitement lié au sultanat de Yogyakarta et à l'océan Indien. Les rituels de sacrifice réguliers de la population locale témoignent de leur profond respect pour la force naturelle de la montagne.",
    },
